TITLE='When Not to Click: Auditing Native Visual Confidence under GUI Target Ambiguity and Distribution Shift'
def pct(v):return 'undefined' if v is None or pd.isna(v) else f'{100*v:.1f}%'
def blocks():
 s=json.loads((ROOT/'results/extended/summary.json').read_text()); op=json.loads((ROOT/'results/external_confirmatory/summary.json').read_text())['operations'];df=pd.read_csv(ROOT/'results/extended/stratified_metrics.csv')
